  files?: UniApp.UploadFileOptionFiles[]
  formData?: Record<string, any>
  name?: string
}
function httpImpl<T>(options: CustomRequestOptions) {
  // 1. 杩斿洖 Promise 瀵硅薄
  return new Promise<T>(async (resolve, reject) => {
    // 鏄剧ずloading
    const showLoading = options.showLoading !== false;

    if (showLoading) {
      uni.showLoading({
        mask: true,
        title: options.loadingText || '鍔犺浇涓?
      });
    }

    // 鍒濆鍖栬姹傚ご
    const headers: Record<string, string> = {};

    // 涓烘墍鏈夋帴鍙ｆ坊鍔燗uthorization璇锋眰澶?
    const token = userStore.getToken();
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    uni.request({
      ...options,
      header: {
        ...headers,
        ...options.header
      },
      dataType: 'json',
      // #ifndef MP-WEIXIN
      responseType: 'json',
      // #endif
      // 鍝嶅簲鎴愬姛
      success: async (res) => {
        if(res.header['x-encrypt'] == "true") {
          const decryptor = new JSEncrypt();
          decryptor.setPrivateKey('');
          const aesKeyBase64 = decryptor.decrypt(res.data.key);
          const aesKey = CryptoJS.enc.Base64.parse(aesKeyBase64);
          const iv = CryptoJS.enc.Hex.parse("00000000000000000000000000000000");
          const decrypted = CryptoJS.AES.decrypt(res.data.data, aesKey, {
            iv: iv,
            mode: CryptoJS.mode.CBC,
            padding: CryptoJS.pad.Pkcs7
          });
          const decryptedText = decrypted.toString(CryptoJS.enc.Utf8);
          const json = JSON.parse(decryptedText);
          res.data = json
        }
        const responseData = res.data
        console.log(options.url, {request: options, response: res});
        const { code, msg, data } = responseData
          // 闅愯棌loading
          if (showLoading) {
            uni.hideLoading();
          }

          // 妫€鏌TTP鐘舵€佺爜401
          if (res.statusCode === 401) {
            // 鐩存帴閲嶅畾鍚戝埌鐧诲綍椤甸潰
            uni.redirectTo({
              url: '/pages/login'
            })
            return reject(res)
          }

          // 棣栧厛妫€鏌ユ槸鍚︿负涓氬姟澶辫触涓旈渶瑕佺櫥褰?
          if(code === 401) {
            // 鐩存帴閲嶅畾鍚戝埌鐧诲綍椤甸潰
            uni.redirectTo({
              url: '/pages/login'
            })
            return reject(res)
          }

          // 妫€鏌ユ槸鍚︿负鍏朵粬涓氬姟澶辫触
          if(code != 200) {
            uni.showToast({
              icon: 'none',
              title: msg || '绯荤粺寮傚父锛岃鑱旂郴瀹㈡湇',
            })
            return reject(res)
          }

          // 澶勭悊鎴愬姛鐘舵€?
          if (res.statusCode >= 200 && res.statusCode < 300) {
            return resolve(responseData as T)
          }

          // 澶勭悊鍏朵粬HTTP閿欒
          reject(res)
      },
      // 鍝嶅簲澶辫触
      fail(err) {
        // 闅愯棌loading
        if (showLoading) {
          uni.hideLoading();
        }
        uni.showToast({
          icon: 'none',
          title: '缃戠粶閿欒锛屾崲涓綉缁滆瘯璇?,
        })
        reject(err)
      },
    })
  })
}

/**
 * GET 璇锋眰
 * @param url 鍚庡彴鍦板潃
 * @param query 璇锋眰query鍙傛暟
 * @param header 璇锋眰澶达紝榛樿涓簀son鏍煎紡
 * @returns
 */
export function httpGet<T>(url: string, query?: Record<string, any>, header?: Record<string, any>, options?: Partial<CustomRequestOptions>) {
  return httpImpl<T>({
    url,
    query,
    method: 'GET',
    header,
    ...options,
  })
}

/**
 * POST 璇锋眰
 * @param url 鍚庡彴鍦板潃
 * @param data 璇锋眰body鍙傛暟
 * @param query 璇锋眰query鍙傛暟锛宲ost璇锋眰涔熸敮鎸乹uery锛屽緢澶氬井淇℃帴鍙ｉ兘闇€瑕?
 * @param header 璇锋眰澶达紝榛樿涓簀son鏍煎紡
 * @returns
 */
export function httpPost<T>(url: string, data?: Record<string, any>, header?: Record<string, any>, options?: Partial<CustomRequestOptions>) {
  return httpImpl<T>({
    url,
    data,
    method: 'POST',
    header,
    ...options,
  })
}
/**
 * PUT 璇锋眰
 */
export function httpPut<T>(url: string, data?: Record<string, any>, header?: Record<string, any>, options?: Partial<CustomRequestOptions>) {
  return httpImpl<T>({
    url,
    data,
    method: 'PUT',
    header,
    ...options,
  })
}

/**
 * DELETE 璇锋眰锛堟棤璇锋眰浣擄紝浠?query锛?
 */
export function httpDelete<T>(url: string, query?: Record<string, any>, header?: Record<string, any>, options?: Partial<CustomRequestOptions>) {
  return httpImpl<T>({
    url,
    query,
    method: 'DELETE',
    header,
    ...options,
  })
}

/**
 * 鏂囦欢涓婁紶锛坲ni.uploadFile锛夛紝URL / query / Token 涓?{@link http} 涓€鑷达紝涓氬姟鐮佸鐞嗕笌 {@link http} 涓€鑷?
 */
export function httpFile<T>(
  url: string,
  data: HttpFileUploadData,
  config: Partial<CustomRequestOptions> = {},
) {
  const showLoading = config.showLoading !== false

  return new Promise<T>((resolve, reject) => {
    if (showLoading) {
      uni.showLoading({
        mask: true,
        title: config.loadingText || '鍔犺浇涓?,
      })
    }

    const prepared = applyHttpRequestOptions({
      url,
      method: 'POST',
      header: config.header,
      query: config.query,
      ...config,
    })

    uni.uploadFile({
      url: prepared.url!,
      header: prepared.header,
      timeout: prepared.timeout,
      filePath: data.filePath,
      files: data.files,
      formData: data.formData,
      name: data.name || 'file',
      success: (res) => {
        if (showLoading) {
          uni.hideLoading()
        }

        let responseData: any
        try {
          responseData = typeof res.data === 'string' ? JSON.parse(res.data) : res.data
        } catch {
          uni.showToast({
            icon: 'none',
            title: '鍝嶅簲瑙ｆ瀽澶辫触',
          })
          return reject(res)
        }

        console.log(url, { request: { url, data, config }, response: res })

        const { code, msg } = responseData

        if (res.statusCode === 401) {
          uni.redirectTo({
            url: '/pages/login',
          })
          return reject(res)
        }

        if (code === 401) {
          uni.redirectTo({
            url: '/pages/login',
          })
          return reject(res)
        }

        if (code != 200) {
          if (!config.hideErrorToast) {
            uni.showToast({
              icon: 'none',
              title: msg || '绯荤粺寮傚父锛岃鑱旂郴瀹㈡湇',
            })
          }
          return reject(res)
        }

        if (res.statusCode >= 200 && res.statusCode < 300) {
          return resolve(responseData as T)
        }

        reject(res)
      },
      fail: (err) => {
        if (showLoading) {
          uni.hideLoading()
        }
        if (!config.hideErrorToast) {
          uni.showToast({
            icon: 'none',
            title: '缃戠粶閿欒锛屾崲涓綉缁滆瘯璇?,
          })
        }
        reject(err)
      },
    })
  })
}

export type Http = (typeof httpImpl) & {
  get: typeof httpGet
  post: typeof httpPost
  put: typeof httpPut
  delete: typeof httpDelete
  file: typeof httpFile
}

/** 鏀寔涓?axios 绫讳技鐨?API锛歡et / post / put / delete / file */
export const http = Object.assign(httpImpl, {
  get: httpGet,
  post: httpPost,
  put: httpPut,
  delete: httpDelete,
  file: httpFile,
}) as Http



